  "code": "import re\n\n\n_HEADING_RE = re.compile(r\"^\\s*\\ufeff*\\f*PROPOSED\\s+COMPLIANCE\\s+ORDER\\s*$\", re.IGNORECASE)\n_STOP_RE = re.compile(\n    r\"^(it\\s+is\\s+requested(?:\\s*\\(not\\s+mandated\\))?|response\\s+options|response\\s+to\\s+this\\s+notice|\"\n    r\"enclosures?:|sincerely|respectfully|cc\\b|attachments?)\",\n    re.IGNORECASE,\n)\n_PAGE_RE = re.compile(r\"^(page\\s+\\d+(?:\\s+of\\s+\\d+)?)$\", re.IGNORECASE)\n_TOP_LEVEL_LABEL_RE = re.compile(r\"^\\s*[A-Z]\\.\\s*$\")\n_FINAL_ORDER_RE = re.compile(r\"\\bfinal\\s+order\\b\", re.IGNORECASE)\n_PRIMARY_ACTION_RE = re.compile(\n    r\"\\b(complete|correct|repair|replace|install|modify|revise|update|develop|implement|\"\n    r\"conduct|perform|review|analy[sz]e|train|inspect|exercise|survey|recoat|protect|\"\n    r\"evaluate|measure|finish|submit a schedule|design)\\b\",\n    re.IGNORECASE,\n)\n_SECONDARY_ONLY_RE = re.compile(\n    r\"\\b(submit|provide|send)\\b.{0,80}\\b(documentation|documents|records?|evidence|proof|copies|update)\\b\",\n    re.IGNORECASE,\n)\n_REPORT_ONLY_RE = re.compile(\n    r\"\\b(report(?:s|ing)?|progress|follow[- ]?up|outstanding work necessary to implement|\"\n    r\"days thereafter|until all work necessary to implement|91st day|every\\s+\\d+\\s+days?)\\b\",\n    re.IGNORECASE,\n)\n_DIGIT_TIME_RE = re.compile(\n    r\"\\b(?P<num>\\d{1,4})\\s*(?:\\(\\s*\\d{1,4}\\s*\\))?\\s*,?\\s*(?P<unit>days?|months?|years?)\\b\",\n    re.IGNORECASE,\n)\n_WORD_NUMS = {\n    \"one\": 1,\n    \"two\": 2,\n    \"three\": 3,\n    \"four\": 4,\n    \"five\": 5,\n    \"six\": 6,\n    \"seven\": 7,\n    \"eight\": 8,\n    \"nine\": 9,\n    \"ten\": 10,\n    \"eleven\": 11,\n    \"twelve\": 12,\n    \"eighteen\": 18,\n    \"twenty\": 20,\n    \"twenty-four\": 24,\n}\n_WORD_TIME_RE = re.compile(\n    r\"\\b(?P<word>one|two|three|four|five|six|seven|eight|nine|ten|eleven|twelve|eighteen|twenty|twenty-four)\"\n    r\"\\s*(?:\\(\\s*(?P<paren>\\d{1,4})\\s*\\))?\\s*,?\\s*(?P<unit>days?|months?|years?)\\b\",\n    re.IGNORECASE,\n)\n\n\ndef _norm(text: str) -> str:\n    return re.sub(r\"\\s+\", \" \", (text or \"\").replace(\"\\ufeff\", \"\").replace(\"\\f\", \"\")).strip()\n\n\ndef _materialize(items: list[dict], text_key: str) -> list[dict]:\n    return [\n        {\n            \"text\": item.get(text_key) or \"\",\n            \"page_no\": item.get(\"page_no\"),\n            \"line_no\": item.get(\"line_no\"),\n            \"paragraph_no\": item.get(\"paragraph_no\"),\n        }\n        for item in items\n        if isinstance(item, dict)\n    ]\n\n\ndef _split_blocks(lines: list[dict], start_idx: int) -> list[list[dict]]:\n    blocks: list[list[dict]] = []\n    current: list[dict] = []\n    for item in lines[start_idx + 1 :]:\n        text = _norm(item.get(\"text\") or \"\")\n        if not text or _PAGE_RE.fullmatch(text):\n            continue\n        if _STOP_RE.match(text):\n            break\n        if _TOP_LEVEL_LABEL_RE.fullmatch(text):\n            if current:\n                blocks.append(current)\n            current = [item]\n            continue\n        if current:\n            current.append(item)\n    if current:\n        blocks.append(current)\n    return blocks\n\n\ndef _iter_deadlines(text: str):\n    lower = text.lower()\n    for match in _DIGIT_TIME_RE.finditer(lower):\n        num = int(match.group(\"num\"))\n        unit = match.group(\"unit\").lower()\n        yield match.start(), num, unit\n    for match in _WORD_TIME_RE.finditer(lower):\n        num = int(match.group(\"paren\") or _WORD_NUMS[match.group(\"word\").lower()])\n        unit = match.group(\"unit\").lower()\n        yield match.start(), num, unit\n\n\ndef _to_days(num: int, unit: str) -> int:\n    if unit.startswith(\"day\"):\n        return num\n    if unit.startswith(\"month\"):\n        return num * 30\n    return num * 365\n\n\ndef _sentence_spans(text: str) -> list[str]:\n    parts = re.split(r\"(?<=[.!?])\\s+\", text)\n    return [part.strip() for part in parts if part.strip()]\n\n\ndef _best_deadline_in_block(text: str) -> tuple[int, str] | None:\n    if not _FINAL_ORDER_RE.search(text):\n        return None\n\n    best: tuple[int, str] | None = None\n    for sentence in _sentence_spans(text):\n        if \"final order\" not in sentence.lower():\n            continue\n        if _REPORT_ONLY_RE.search(sentence):\n            continue\n\n        candidates = list(_iter_deadlines(sentence))\n        if not candidates:\n            continue\n\n        actionable = _PRIMARY_ACTION_RE.search(sentence) is not None\n        secondary_only = _SECONDARY_ONLY_RE.search(sentence) is not None and not actionable\n        if not actionable and secondary_only:\n            continue\n\n        for _, num, unit in candidates:\n            days = _to_days(num, unit)\n            if best is None or days > best[0]:\n                best = (days, sentence)\n\n    if best is not None:\n        return best\n\n    if _REPORT_ONLY_RE.search(text):\n        return None\n\n    candidates = list(_iter_deadlines(text))\n    if not candidates:\n        return None\n\n    actionable = _PRIMARY_ACTION_RE.search(text) is not None\n    secondary_only = _SECONDARY_ONLY_RE.search(text) is not None and not actionable\n    if not actionable and secondary_only:\n        return None\n\n    num, unit = max((num, unit) for _, num, unit in candidates, key=lambda pair: _to_days(pair[0], pair[1]))\n    return _to_days(num, unit), text\n\n\ndef rule_proposed_compliance_order_deadlines(doc: dict) -> list[dict]:\n    try:\n        lines = _materialize(doc.get(\"lines\") or [], \"text\")\n        if not lines:\n            lines = _materialize(doc.get(\"paragraphs\") or [], \"text\")\n        if not lines:\n            raw_text = doc.get(\"text\") or \"\"\n            if not raw_text:\n                return []\n            lines = [{\"text\": raw_text, \"page_no\": None, \"line_no\": None, \"paragraph_no\": None}]\n\n        heading_indices = [\n            i for i, item in enumerate(lines) if _HEADING_RE.search(_norm(item.get(\"text\") or \"\"))\n        ]\n        if not heading_indices:\n            return []\n\n        best_span: dict | None = None\n        best_days = -1\n\n        for block in _split_blocks(lines, heading_indices[-1]):\n            block_text = \"\\n\".join(_norm(item.get(\"text\") or \"\") for item in block if _norm(item.get(\"text\") or \"\"))\n            candidate = _best_deadline_in_block(block_text)\n            if candidate is None:\n                continue\n\n            days, best_text = candidate\n            if days <= best_days:\n                continue\n\n            first = block[0]\n            span = {\"text\": best_text}\n            for key in (\"page_no\", \"line_no\", \"paragraph_no\"):\n                value = first.get(key)\n                if value is not None:\n                    span[key] = value\n            best_days = days\n            best_span = span\n\n        return [best_span] if best_span is not None else []\n    except Exception:\n        return []\n",
